mapper.select:
select * from b_tcyr_cpa_colliding_task
where is_del = 1

    AND package_names like concat("%", #{packageName},"%")


    AND enabled = #{enabled}


    AND colliding_time  >=  #{collidingDateBegin}
    AND colliding_time  <=  #{collidingDateEnd}

order by colliding_date desc, colliding_time asc, create_time asc

select supply_rule_info
from b_tcyr_cpa_colliding_task
where id = #{taskId}
